(1, '676e78213ac9f', NULL, 'Advanced WooCommerce Support', 'We have detected you are running WooCommerce. Upgrade to AIOSEO Pro to unlock our advanced eCommerce SEO features, including SEO for Product Categories and more.', 'info', '[\"all\"]', NULL, 'woo-upsell', '2024-12-27 09:49:21', NULL, 'Upgrade to Pro', 'https://aioseo.com/lite-upgrade/?utm_source=WordPress&utm_campaign=liteplugin&utm_medium=woo-notification-upsell', NULL, NULL, 0, 0, '2024-12-27 09:49:21', '2024-12-27 09:49:21'),
(2, '676e78213ad09', NULL, 'Advanced WooCommerce Support', 'We have detected you are running WooCommerce. Upgrade to AIOSEO Pro to unlock our advanced eCommerce SEO features, including SEO for Product Categories and more.', 'info', '[\"all\"]', NULL, 'woo-upsell', '2024-12-27 09:49:21', NULL, 'Upgrade to Pro', 'https://aioseo.com/lite-upgrade/?utm_source=WordPress&utm_campaign=liteplugin&utm_medium=woo-notification-upsell', NULL, NULL, 0, 0, '2024-12-27 09:49:21', '2024-12-27 09:49:21'),
(3, '676e782147be8', NULL, 'Have you connected your site to Google Search Console?', 'All in One SEO can now verify whether your site is correctly verified with Google Search Console and that your sitemaps have been submitted correctly. Connect with Google Search Console now to ensure your content is being added to Google as soon as possible for increased rankings.', 'warning', '[\"all\"]', NULL, 'search-console-site-not-connected', '2024-12-27 09:49:21', NULL, 'Connect to Google Search Console', 'https://route#aioseo-settings&aioseo-scroll=google-search-console-settings&aioseo-highlight=google-search-console-settings:webmaster-tools?activetool=googleSearchConsole', NULL, NULL, 0, 0, '2024-12-27 09:49:21', '2024-12-27 09:49:21'),
(4, '676e782147c6e', NULL, 'Have you connected your site to Google Search Console?', 'All in One SEO can now verify whether your site is correctly verified with Google Search Console and that your sitemaps have been submitted correctly. Connect with Google Search Console now to ensure your content is being added to Google as soon as possible for increased rankings.', 'warning', '[\"all\"]', NULL, 'search-console-site-not-connected', '2024-12-27 09:49:21', NULL, 'Connect to Google Search Console', 'https://route#aioseo-settings&aioseo-scroll=google-search-console-settings&aioseo-highlight=google-search-console-settings:webmaster-tools?activetool=googleSearchConsole', NULL, NULL, 0, 0, '2024-12-27 09:49:21', '2024-12-27 09:49:21'),
(5, '676e78215cc08', NULL, 'Conflicting Plugins Detected', 'Warning: AIOSEO has detected other active SEO or sitemap plugins. We recommend that you deactivate the following plugins to prevent any conflicts:<ul><li><strong>Rank Math SEO</strong></li></ul>', 'error', '[\"all\"]', NULL, 'conflicting-plugins', '2024-12-27 09:49:21', NULL, 'Fix Now', 'http://action#sitemap/deactivate-conflicting-plugins?refresh', 'Remind Me Later', 'http://action#notification/conflicting-plugins-reminder', 0, 0, '2024-12-27 09:49:21', '2024-12-29 08:54:41');
