INSERT INTO `wpx_learnpress_courses` (`ID`, `json`, `price_to_sort`, `is_sale`, `post_author`, `post_date_gmt`, `post_content`, `post_title`, `post_status`, `post_name`, `menu_order`, `lang`) VALUES
(2060, '{\"ID\":2060,\"post_author\":\"1\",\"post_date_gmt\":\"2024-12-16 21:11:46\",\"post_title\":\"Course 1\",\"post_status\":\"publish\",\"post_name\":\"course-1\",\"price_to_sort\":0,\"is_sale\":0,\"lang\":null,\"meta_data\":{\"_lp_duration\":\"10 week\",\"_lp_max_students\":\"0\",\"_lp_students\":\"0\",\"_lp_retake_count\":\"0\",\"_lp_featured\":\"no\",\"_lp_has_finish\":\"yes\",\"_lp_course_result\":\"evaluate_lesson\",\"_lp_passing_condition\":80,\"_lp_sample_data\":\"yes\",\"_lp_requirements\":[\"Magnitudine invidus simile appellamus aequo habeatur offensione laelius nocent ei faciendi inveniri\",\"Tantas pulchritudo stuprata t videor orbus stoicis inportuna solebat ita percipitur sequantur magnificentia\",\"Prosunt conati pyrrhonem peteret admonitionis consequens diodorus decimano soles adiungo philosophus pulchritudinem familiaris inquieta occultum\",\"Vivere debent archytam aliquod virtutes deteriora origo intellegetur compellans siti audire istic philosophiae\",\"Contrariae stoicus relictae retineat naturales utuntur que signa optimum quibusdam praeterita ea arcana\",\"Fuit partes ingeniosi me codrum inflammat inscite oratione torquate quippe\",\"Vincunt virtuti gaudeant latina videri complectarsunt disputari restincta defensa tua quandam communiter curatione\",\"Phaedro levis consequens honestatis habeat vestris principes tolluntur dixisset stulti murenam noluerunt illorum liberos morbus\",\"Platoni nolo nobis dicendi isti utilitas quem oris agere vitia\"],\"_lp_target_audiences\":[\"Nostrum ponatur sciant pervertere educatio quiddam poenam improbos praeter concinant dubitant vere\",\"Tardeve alienae subito ingenium censes severe natalis honeste cognitioque ingenium itaque corroborati quicum luxuriae\",\"Paupertas arbitrantur coniunxisset secundum concurrent loquitur temperantiam contingit signum reiecta quoquo sin duas libidinosam\",\"Facilior videris pedes indicia occurrent additis que voluptates indicia vocas faceret libentius plebem inportuna sui\",\"Forte viros antiocho hoc vis videro sapienti iustitia flumine miserum brute mutat longius perpauca\",\"Alter terra stulti itaque divitiis instrumento bono ei habentur eaque amicitias vocatur persem pertinacem\"],\"_lp_key_features\":[\"Liberum abducam duce veniunt debilitates putes videtis primos mox vitio vultus quaerenda\",\"Studio appellocommunia dixisti putaverunt existimare rem latine potius pertinacem natalem oratores certum\",\"Mutat vera permulcet propensus siti theophrastus privatio pollicetur magnarum uti confirmandus\",\"Rebus gestiret quam ages infame neutrum vellem color secrevit reddes verberibus platone oblivionis dubitant\",\"Loquemur pylades vivi laudata ordiendum stare ratione physicis iam complectitur studiose insipiensquo oportet utroque\",\"Captum visa varietate ordiamur beato mallem distinctio vix optime piscis idemque habet contenti\",\"Extrahenda dignitati audeo dubitabit tollerem ingenii potestne eaedem status at ponatur amicitia oroete habuit\",\"Vitiose communia possunt is haeret usitate aliena nocent scribimus dubitabit\",\"Vultis accidisset cari mutat amet contendimus oboediens impedit levem dicerentur habebit corpus\",\"Coniunctio sponte aperiendum metellum diuturnitas leves penitus proferebas affectiones iudicio nullum sitienti diligens reliquo aequo\"],\"_lp_faqs\":[[\"Tantas esse asotos dicerentur possit alienae indignum soletis postumius aliqua ego positum abiecerat dicere?\",\"<p>Graeco inflammat et disputatum diceret plus motum turpiter tardeve causa salebra ignorat plebis intellegit appellat iudicari ambobus sermone<\\/p><p>Iuppiter vellet interest<\\/p>\"],[\"Auctoritatem motus convincunturque paginas istam malis comparandarum liceat levares tutiorem disciplina sapientium disseretur nihilo?\",\"<p>Reprehendi moderatio censent locos beata depravata liceat puerorum venissemus rotundum<\\/p><p>Exposuit accepit academiae insipientium pueri me quonam laudat eorumve usus<\\/p>\"],[\"Videris dicerem qualis ambarum haberent carneade aristoteles consumptum impudens samium confusio es disputatione dixisse?\",\"<p>Vituperanda disiuncta disciplina recuso disciplina testata est mentem iustitiae sanctos<\\/p><p>Parabiles fieri delectatus antiocho claudii dici volo antiquis minuis polemonis tribuunt radicitus<\\/p>\"],[\"Praeclare tum voluptatis infamia seditione accius tollit oppressum sapiente vivi stoicus confirmatae reperies videtis eo?\",\"<p>Errat quali sensibus tanto sin praetore quivere appellat rem apti<\\/p><p>Legem deterritum flagitiosa peripatetici philosophi homerus peripateticorum relinquunt perpetiuntur commissis ceteros finxerit<\\/p><p>Paene nosti refert imperatoriae<\\/p>\"],[\"Quaerere sequatur ipsis sim instrumento quaerenda reperiemus fallare qua antiquis verum?\",\"<p>Similiter relictae ei dubitant murenam atqui dolere hominis vestrum qualem acupenserem oratores sullae temperantiam<\\/p><p>Confusioque litteris natae consulatum uno ipsam interrete nequiter qualem mediocritate rhetoribus sextilio<\\/p>\"],[\"Quovis mortes admirationis uno erat haec putabam interesset aeque oportere mediocribus cenasti?\",\"<p>Frugaliter utraque l omniaque vides maximarum adduceret tribunus longum physicum vitiosum debet divitiis<\\/p><p>Quamquam aestimaretis sitne vanos maximis studebat mos condemnatus nomen cernitur habitare sapienter ei<\\/p><p>Vocabulis concessis ortu dividit<\\/p>\"],[\"Sapientiam beatam defendere intellegam iucundi dicet selectio comparatur affecit opponitur rem graeco beneficium sine videlicet?\",\"<p>Divitem ponatur callidus artis orestem nare surrexit vocant praeterita omnibusque nolo patefactio pertimuit cupiditatum despiciendis libentius ullo caecus ductus<\\/p><p>Flagitiosum ultimas proverbia relictae<\\/p>\"],[\"Appello semel veterum neget triarius integra vocant habendus vere sua quattuor ptolomaeum tempus imperatoriae?\",\"<p>Vestigium ambiguo dictum ambulet ipsa praetermissa asotorum vester privatio adolescentulus easque illustrior statuam necesse expletum malitias varietatem versuta tibi<\\/p><p>Censet deprehensus origo praecipue laetitia noster acerrimus prosunt rhetorice inprudens<\\/p>\"]],\"_lp_featured_review\":\"Luci intercludat censent pylades debent protervam iudicari stabilitatem venit quorum pravitatis adiunxit conclusum repugno cognitioque mari cor vartutis video gravis fuisse habebat similis dubitet moribus quidam egregius explicari exercebantur nescius possent quodsi germen iucunda hominis\",\"_lp_price\":0,\"_lp_regular_price\":\"\",\"_lp_sale_price\":\"\",\"_lp_sale_start\":false,\"_lp_sale_end\":false,\"_lp_allow_course_repurchase\":\"no\",\"_lp_offline_course\":\"no\",\"_lp_block_expire_duration\":\"no\",\"_lp_block_finished\":\"yes\",\"_lp_course_repurchase_option\":\"reset\",\"_lp_level\":\"\",\"_lp_external_link_buy_course\":\"\",\"_lp_offline_lesson_count\":10,\"_lp_deliver_type\":\"private_1_1\",\"_lp_address\":\"\",\"_lp_no_required_enroll\":\"no\",\"post_author\":\"1\",\"_lp_course_material\":null,\"_lp_final_quiz\":\"2170\"},\"image_url\":\"http:\\/\\/localhost:8088\\/wp-content\\/uploads\\/2022\\/02\\/coaching-15.jpg\",\"permalink\":\"\",\"categories\":[],\"tags\":[],\"post_excerpt\":\"\",\"first_item_id\":2061,\"total_items\":{\"count_items\":\"65\",\"lp_lesson\":\"60\",\"lp_quiz\":\"5\"},\"sections_items\":[{\"id\":\"1\",\"section_id\":\"1\",\"order\":\"0\",\"section_order\":\"0\",\"title\":\"Section 1\",\"section_name\":\"Section 1\",\"description\":\"Polemonis commentatus uterque euripidesconcludam sibi utebare solet superiores pro suam\",\"section_description\":\"Polemonis commentatus uterque euripidesconcludam sibi utebare solet superiores pro suam\",\"items\":[{\"id\":\"2061\",\"item_id\":\"2061\",\"order\":\"0\",\"item_order\":\"0\",\"type\":\"lp_lesson\",\"item_type\":\"lp_lesson\",\"title\":\"Lesson 1\",\"preview\":true},{\"id\":\"2062\",\"item_id\":\"2062\",\"order\":\"1\",\"item_order\":\"1\",\"type\":\"lp_lesson\",\"item_type\":\"lp_lesson\",\"title\":\"Lesson 2\",\"preview\":false},{\"id