INSERT INTO `wpx_learnpress_sections` (`section_id`, `section_name`, `section_course_id`, `section_order`, `section_description`) VALUES
(1, 'Section 1', 2060, 0, 'Polemonis commentatus uterque euripidesconcludam sibi utebare solet superiores pro suam'),
(2, 'Section 2', 2060, 1, 'Civitatis fragile nullam kakaw cleanthes initiis oculis habebit facta actiones nihil peducaeus omnes contenti vestra'),
(3, 'Section 3', 2060, 2, 'Adhibebat contineo vestri fidesic risu fecit contemnit unde epulis sanabat'),
(4, 'Section 4', 2060, 3, 'Optimo animo expetendam paucis poterimus admirationis aristoteli consentit pyrrhonem varietatem recordatione absit positum plurimis'),
(5, 'Section 5', 2060, 4, 'Rogatione petitur intellego populari diuturnitas primos fuit cyrenaicos aristonem contendimus pertectam quamvis appellamus heredem epicuri'),
(6, 'Section 1', 2182, 0, 'Uberrimam animi cupiditas plane veteris magister nosmet copiose sextilius clamores'),
(7, 'Section 2', 2182, 1, 'Vincunt salvam maria concessis intellegis capiamus affers vocant serpere permulcet'),
(8, 'Section 3', 2182, 2, 'Civis torqueatur dissimile ipsos utraque instituendarum docet platonis stoicos potestne affecit'),
(9, 'Section 4', 2182, 3, 'Eiusdem arripere vario phaedro agere obscuratur peripatetici corporis habitare traditur adiunxit subito dolorem'),
(10, 'Section 5', 2182, 4, 'Cognitionem dare illorum octavio maximus tributa populorum neglegendi ielunior plurimis sextus optimum'),
(11, 'Section 6', 2182, 5, 'Debent metuit palatum dolori sensim aptius summi stabilitatem conservatorem ferendum licet'),
(12, 'Section 7', 2182, 6, 'Efficiuntur sese videat malane omnia causa gravissimum proferebas materiam ea mediocritate fatebuntur'),
(13, 'Section 8', 2182, 7, 'Fatebuntur fellx sempiternam beatissimum egens iure ait efficiens appellavit me pretiosissimis sua'),
(14, 'Section 9', 2182, 8, 'Debet putas historia longinquum probat temperantiam quasi malo minime se ipsae effecit fugiam animal quoad');
