on\";s:6:\"3.19.6\";s:18:\"nav_menu_locations\";a:4:{s:7:\"primary\";i:68;s:6:\"footer\";i:0;s:11:\"top_bar_nav\";i:0;s:14:\"primary_mobile\";i:118;}s:7:\"backups\";N;s:9:\"smof_init\";s:31:\"Sat, 20 Apr 2024 17:03:36 +0000\";s:19:\"html_scripts_header\";s:509:\"<div class=\"float-icon-hotline\">			\r\n		<ul class =\"left-icon hotline\">\r\n			<li class=\"hotline_float_icon\"><a target=\"_blank\" rel=\"nofollow\" id=\"messengerButton\" href=\"https://zalo.me/0375577911\"><i class=\"fa fa-zalo animated infinite tada\"></i><span>Zalo</span></a></li>\r\n			<li class=\"hotline_float_icon\"><a target=\"_blank\" rel=\"nofollow\" id=\"messengerButton\" href=\"https://www.messenger.com/t/vanhaiweb\"><i class=\"fa fa-messenger animated infinite tada\"></i><span>Facebook</span></a></li>\r\n		</ul>		\r\n</div>\";s:19:\"html_scripts_footer\";s:2280:\"<div class=\"hotline-phone-ring-wrap\">\r\n    <div class=\"hotline-phone-ring\">\r\n        <div class=\"hotline-phone-ring-circle\"></div>\r\n        <div class=\"hotline-phone-ring-circle-fill\"></div>\r\n        <div class=\"hotline-phone-ring-img-circle\"> <a href=\"tel:0898982526\" class=\"pps-btn-img\"> <img src=\"https://netweb.vn/img/hotline/icon.png\" alt=\"so dien thoai\" width=\"50\"> </a></div>\r\n    </div>\r\n    <div class=\"hotline-bar\">\r\n        <a href=\"tel:0898982526\"> <span class=\"text-hotline\">08 9898 2526</span> </a>\r\n    </div>\r\n\r\n</div>\r\n\r\n<script>\r\ndocument.addEventListener(\'DOMContentLoaded\', function () {\r\n    const couponButtons = document.querySelectorAll(\'.wpcd-coupon-button\'); // Lấy tất cả các nút\r\n\r\n    couponButtons.forEach(function (button) {\r\n        button.removeAttribute(\'target\'); // Xóa thuộc tính target=\"_blank\"\r\n        button.setAttribute(\'href\', \'#\'); // Đặt lại href để không chuyển link\r\n\r\n        button.addEventListener(\'click\', function (event) {\r\n            event.preventDefault(); // Ngăn chặn hành vi chuyển hướng mặc định\r\n\r\n            // Sao chép mã giảm giá\r\n            const couponText = button.getAttribute(\'data-clipboard-text\');\r\n            if (couponText) {\r\n                navigator.clipboard.writeText(couponText) // Sao chép mã giảm giá vào clipboard\r\n                    .then(() => {\r\n                        // Thay đổi tooltip để báo thành công\r\n                        const originalTitle = button.getAttribute(\'title\'); // Lưu tooltip gốc\r\n                        button.setAttribute(\'title\', \'Đã sao chép mã giảm giá!\'); // Đổi tooltip\r\n                        \r\n                        // Hiển thị tooltip cập nhật\r\n                        const tooltipEvent = new Event(\'mouseover\');\r\n                        button.dispatchEvent(tooltipEvent);\r\n\r\n                        // Trả lại tooltip gốc sau 2 giây\r\n                        setTimeout(() => {\r\n                            button.setAttribute(\'title\', originalTitle);\r\n                        }, 2000);\r\n                    })\r\n                    .catch(err => console.error(\'Không thể sao chép mã giảm giá:\', err));\r\n            }\r\n        });\r\n    });\r\n});\r\n\r\n\r\n</script>\";s:23:\"html_scripts_after_body\";s:0:\"\";s:24:\"html_scripts_before_body\";s:0:\"\";s:15:\"html_custom_css\";s:6726:\".hotline-phone-ring-circle{width:85px;height:85px;top:10px;left:10px;position:absolute;background-color:transparent;border-radius:100%;border:2px solid #e60808;-webkit-animation:phonering-alo-circle-anim 1.2s infinite ease-in-out;animation:phonering-alo-circle-anim 1.2s infinite ease-in-out;transition:all .5s;-webkit-transform-origin:50% 50%;-ms-transform-origin:50% 50%;transform-origin:50% 50%;opacity:.5}\r\n.hotline-phone-ring-circle-fill{width:55px;height:55px;top:22px;left:26px;position:absolute;background-color:rgba(230,8,8,.7);border-radius:100%;border:2px solid transparent;-webkit-animation:phonering-alo-circle-fill-anim 2.3s infinite ease-in-out;animation:phonering-alo-circle-fill-anim 2.3s infinite ease-in-out;transition:all .5s;-webkit-transform-origin:50% 50%;-ms-transform-origin:50% 50%;transform-origin:50% 50%}\r\n.hotline-phone-ring-img-circle{background-color:#e4212a;width:33px;height:33px;top:33px;left:37px;position:absolute;background-size:20px;border-radius:100%;border:2px solid transparent;-webkit-animation:phonering-alo-circle-img-anim 1s infinite ease-in-out;animation:phonering-alo-circle-img-anim 1s infinite ease-in-out;-webkit-transform-origin:50% 50%;-ms-transform-origin:50% 50%;transform-origin:50% 50%;display:-webkit-box;display:-webkit-flex;display:-ms-flexbox;display:flex;align-items:center;justify-content:center}\r\n.hotline-phone-ring-img-circle .pps-btn-img{display:-webkit-box;display:-webkit-flex;display:-ms-flexbox;display:flex}\r\n.hotline-phone-ring-img-circle .pps-btn-img img{width:20px;height:20px}\r\n\r\n.hotline-bar{position:absolute;background:#e88a25;background:-webkit-linear-gradient(left,#e88a25,#d40000);background:-o-linear-gradient(right,#e88a25,#d40000);background:-moz-linear-gradient(right,#e88a25,#d40000);background: #F58B9E;height:40px;width:200px;line-height:40px;border-radius:3px;padding:0 10px;background-size:100%;cursor:pointer;transition:all .8s;-webkit-transition:all .8s;z-index:9;box-shadow:0 14px 28px rgba(0,0,0,.25),0 10px 10px rgba(0,0,0,.1);border-radius:50px !important;border:2px solid #F58B9E;left:33px;bottom:37px}.hotline-bar>a{color:#fff;text-decoration:none;font-size:16px;font-weight:600;text-indent:50px;display:block;letter-spacing:1px;line-height:38px;font-family:Arial}.hotline-bar>a:hover,.hotline-bar>a:active{color:#fff}@-webkit-keyframes phonering-alo-circle-anim{0%{-webkit-transform:rotate(0) scale(.5) skew(1deg);-webkit-opacity:.1}30%{-webkit-transform:rotate(0) scale(.7) skew(1deg);-webkit-opacity:.5}100%{-webkit-transform:rotate(0) scale(1) skew(1deg);-webkit-opacity:.1}}@-webkit-keyframes phonering-alo-circle-fill-anim{0%{-webkit-transform:rotate(0) scale(.7) skew(1deg);opacity:.6}50%{-webkit-transform:rotate(0) scale(1) skew(1deg);opacity:.6}100%{-webkit-transform:rotate(0) scale(.7) skew(1deg);opacity:.6}}@-webkit-keyframes phonering-alo-circle-img-anim{0%{-webkit-transform:rotate(0) scale(1) skew(1deg)}10%{-webkit-transform:rotate(-25deg) scale(1) skew(1deg)}20%{-webkit-transform:rotate(25deg) scale(1) skew(1deg)}30%{-webkit-transform:rotate(-25deg) scale(1) skew(1deg)}40%{-webkit-transform:rotate(25deg) scale(1) skew(1deg)}50%{-webkit-transform:rotate(0) scale(1) skew(1deg)}100%{-webkit-transform:rotate(0) scale(1) skew(1deg)}}@media (max-width:768px){.hotline-bar{display:none}}\r\n\r\n.hotline-phone-ring-img-circle .pps-btn-img img {\r\n    width: 20px;\r\n    height: 20px;\r\n}\r\nimg {\r\n    border: none;\r\n}\r\n\r\n\r\n.hotline-phone-ring-wrap {\r\n    position: fixed !important;\r\n    bottom: 0;\r\n    left: 0;\r\n    z-index: 1111111;\r\n}\r\n\r\n.hotline-phone-ring {\r\n    position: relative;\r\n    visibility: visible;\r\n    background-color: transparent;\r\n    width: 110px;\r\n    height: 110px;\r\n    cursor: pointer;\r\n    z-index: 11;\r\n    -webkit-backface-visibility: hidden;\r\n    -webkit-transform: translateZ(0);\r\n    transition: visibility .5s;\r\n    left: 0;\r\n    bottom: 0;\r\n    display: block;\r\n}\r\n\r\n\r\n.float-icon-hotline {\r\n    display: block;\r\n    width: 40px;\r\n    position: fixed;\r\n    bottom: 85px;\r\n    left: 33px;\r\n    z-index: 999999;\r\n}\r\n	\r\n\r\n.float-icon-hotline ul {\r\n    display: block;\r\n    width: 100%;\r\n    padding-left: 0;\r\n    margin-bottom: 0;\r\n}\r\n.float-icon-hotline ul li {\r\n    display: block;\r\n    width: 100%;\r\n    position: relative;\r\n    margin-bottom: 10px;\r\n    cursor: pointer;\r\n}\r\n.float-icon-hotline ul li a#messengerButton {\r\n    padding: 0px !important;\r\n    background: transparent !important;\r\n    border: 0px !important;\r\n}\r\n@media only screen and (min-width: 960px)\r\n{\r\n	.float-icon-hotline ul li .fa {\