(6, 5, '_messages', 'a:22:{s:12:\"mail_sent_ok\";s:45:\"Thank you for your message. It has been sent.\";s:12:\"mail_sent_ng\";s:71:\"There was an error trying to send your message. Please try again later.\";s:16:\"validation_error\";s:61:\"One or more fields have an error. Please check and try again.\";s:4:\"spam\";s:71:\"There was an error trying to send your message. Please try again later.\";s:12:\"accept_terms\";s:69:\"You must accept the terms and conditions before sending your message.\";s:16:\"invalid_required\";s:22:\"The field is required.\";s:16:\"invalid_too_long\";s:22:\"The field is too long.\";s:17:\"invalid_too_short\";s:23:\"The field is too short.\";s:13:\"upload_failed\";s:36:\"Tải file lên không thành công.\";s:24:\"upload_file_type_invalid\";s:69:\"Bạn không được phép tải lên file theo định dạng này.\";s:21:\"upload_file_too_large\";s:50:\"Dung lượng file được tải lên quá lớn.\";s:23:\"upload_failed_php_error\";s:36:\"Tải file lên không thành công.\";s:12:\"invalid_date\";s:61:\"Vui lòng nhập ngày tháng theo định dạng YYYY-MM-DD.\";s:14:\"date_too_early\";s:64:\"Trường dữ liệu này có ngày sớm hơn ngày cho phép.\";s:13:\"date_too_late\";s:64:\"Trường dữ liệu này có ngày trễ hơn ngày cho phép.\";s:14:\"invalid_number\";s:37:\"Vui lòng nhập vào một con số.\";s:16:\"number_too_small\";s:57:\"Trường dữ liệu này có một con số quá nhỏ.\";s:16:\"number_too_large\";s:57:\"Trường dữ liệu này có một con số quá lớn.\";s:23:\"quiz_answer_not_correct\";s:30:\"Câu trả lời chưa đúng.\";s:13:\"invalid_email\";s:36:\"Vui lòng nhập địa chỉ email.\";s:11:\"invalid_url\";s:21:\"Vui lòng nhập URL.\";s:11:\"invalid_tel\";s:38:\"Vui lòng nhập số điện thoại.\";}'),
